import json
import csv
import os
import base64


def task_func(raw_string, filename, output_dir):
    def _cell(value):
        if value is None:
            return ""
        if isinstance(value, (dict, list, tuple)):
            return json.dumps(value, ensure_ascii=False)
        return str(value)

    def _write_rows(path, headers, rows):
        with open(path, "w", newline="", encoding="utf-8") as f:
            writer = csv.writer(f)
            if headers is not None:
                writer.writerow(headers)
            writer.writerows(rows)

    decoded = base64.b64decode(raw_string)
    json_text = decoded.decode("utf-8")
    data = json.loads(json_text)

    output_dir = os.fspath(output_dir) if output_dir else "."
    os.makedirs(output_dir, exist_ok=True)

    filename = os.fspath(filename)
    if not filename.lower().endswith(".csv"):
        filename += ".csv"

    file_path = os.path.join(output_dir, filename)

    if isinstance(data, list):
        if not data:
            _write_rows(file_path, None, [])
        elif all(isinstance(item, dict) for item in data):
            headers = []
            seen = set()
            for item in data:
                for key in item.keys():
                    if key not in seen:
                        seen.add(key)
                        headers.append(key)
            rows = [[_cell(item.get(h, "")) for h in headers] for item in data]
            _write_rows(file_path, headers, rows)
        elif all(isinstance(item, (list, tuple)) for item in data):
            max_len = max(len(item) for item in data)
            headers = [f"column_{i + 1}" for i in range(max_len)]
            rows = []
            for item in data:
                row = [_cell(v) for v in item] + [""] * (max_len - len(item))
                rows.append(row)
            _write_rows(file_path, headers, rows)
        else:
            rows = [[_cell(item)] for item in data]
            _write_rows(file_path, ["value"], rows)
    elif isinstance(data, dict):
        values_are_lists = bool(data) and all(isinstance(v, (list, tuple)) for v in data.values())
        if values_are_lists:
            lengths = {len(v) for v in data.values()}
            headers = list(data.keys())
            if len(lengths) == 1:
                n = next(iter(lengths), 0)
                rows = [[_cell(data[h][i]) for h in headers] for i in range(n)]
            else:
                max_len = max(lengths) if lengths else 0
                rows = []
                for i in range(max_len):
                    row = []
                    for h in headers:
                        values = data[h]
                        row.append(_cell(values[i]) if i < len(values) else "")
                    rows.append(row)
            _write_rows(file_path, headers, rows)
        else:
            headers = list(data.keys())
            row = [_cell(data[h]) for h in headers]
            _write_rows(file_path, headers, [row])
    else:
        _write_rows(file_path, ["value"], [[_cell(data)]])

    return file_path
